private fun icon(name: String, vararg paths: Pair<String, Float>): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 256f,
        viewportHeight = 256f,
    ).apply {
        paths.forEach { (data, alpha) ->
            addPath(
                pathData = PathParser().parsePathString(data).toNodes(),
                fill = SolidColor(Color.Black),
                fillAlpha = alpha,
            )
        }
    }.build()
